 1→/** Helper to extract the type of a single element in an array of elements */
 2→export type Unpacked<T> = T extends (infer U)[] ? U : T;
 3→
 4→/** Helper to a record that optionally omits some fields when using an enum as a record's key */
 5→export type PartialRecord<K extends PropertyKey, T> = {
 6→  [P in K]?: T;
 7→};
 8→
 9→/** Helper that takes in an object of key/value pairs and returns an object of key/value pairs where only one value is required */
10→export type RequireOnlyOne<T, Keys extends keyof T = keyof T> = Pick<
11→  T,
12→  Exclude<keyof T, Keys>
13→> &
14→  {
15→    [K in Keys]-?: Required<Pick<T, K>> &
16→      Partial<Record<Exclude<Keys, K>, undefined>>;
17→  }[Keys];
18→
19→/**  Helper that takes in an object of key/value pairs and returns an object of key/value pairs where at least one value is required */
20→export type RequireAtLeastOne<T, Keys extends keyof T = keyof T> = Pick<
21→  T,
22→  Exclude<keyof T, Keys>
23→> &
24→  {
25→    [K in Keys]-?: Required<Pick<T, K>> & Partial<Pick<T, Exclude<Keys, K>>>;
26→  }[Keys];
27→
28→/**  Helper that takes in an object of key/value pairs and returns an object of key/value pairs where none or at most one value is required */
29→export type RequireAtMostOne<T, Keys extends keyof T = keyof T> = Partial<
30→  RequireOnlyOne<T, Keys>
31→>;
32→
33→/** Helper that takes in an object of key/value pairs and returns an inverted object with the key/value pairs swapped */
34→export type InvertedObject<T extends Record<PropertyKey, PropertyKey>> = {
35→  [K in keyof T as T[K]]: K;
36→};
37→
38→/** Helper to require either of two types - not both. */
39→export type OneOf<T1, T2> =
40→  | (T1 & Partial<Record<Exclude<keyof T2, keyof T1>, never>>)
41→  | (T2 & Partial<Record<Exclude<keyof T1, keyof T2>, never>>);
42→
43→/** Helper to recursively require only a partial set of fields on a nested object */
44→export type Subset<K> = {
45→  [S in keyof K]?: K[S] extends object ? Subset<K[S]> : K[S];
46→};
47→
48→/** Helper function that takes in a complex typescript type and evaluates it for easy debugging */
49→export type Evaluated<T> = {} & { [P in keyof T]: T[P] };
50→
51→/** Helper to identify field K in object T as optional */
52→export type Optional<T, K extends keyof T> = Pick<Partial<T>, K> & Omit<T, K>;
53→
54→export interface StringMap {
55→  [index: string]: string;
56→}
