 1→import { reportError } from "../errorReporting";
 2→
 3→const headers = new Headers({
 4→  "Content-Type": "application/json",
 5→});
 6→
 7→export const post = async (
 8→  url: string,
 9→  body: unknown,
10→  handleError?: (e: Error) => void,
11→) => {
12→  try {
13→    const options: RequestInit = {
14→      body: JSON.stringify(body),
15→      credentials: "include",
16→      headers,
17→      method: "POST",
18→    };
19→    const response = await fetch(url, options);
20→    if (!response.ok) {
21→      throw new Error(getErrorMessage(response, "POST"));
22→    }
23→    return response;
24→  } catch (e) {
25→    const err = e instanceof Error ? e : new Error(JSON.stringify(e));
26→    reportError(err).warning();
27→    handleError?.(err);
28→  }
