 15→
 16→export const Default: Story = {
 17→  render: () => {
 18→    const [open, setOpen] = useState(false);
 19→    const triggerRef = useRef<HTMLButtonElement>(null);
 20→    return (
 21→      <div style={{ padding: 100 }}>
 22→        <Button ref={triggerRef} onClick={() => setOpen(true)}>
 23→          Delete Item
 24→        </Button>
 25→        <Popconfirm
 26→          open={open}
 27→          setOpen={setOpen}
 28→          refEl={triggerRef}
 29→          onConfirm={() => setOpen(false)}
 30→        >
 31→          Are you sure you want to delete this item?
 32→        </Popconfirm>
 33→      </div>
 34→    );
 35→  },
